//-- POWER

void sx1276_rfpower_calc(const int8_t power_dbm, int8_t* sx_power, int8_t* actual_power_dbm)
{
    if (power_dbm >= POWER_17_DBM) {
        *sx_power = 127;
        *actual_power_dbm = 17;
    } else if (power_dbm >= POWER_14_DBM) {
        *sx_power = 124;
        *actual_power_dbm = 14;
    } else {
        *sx_power = 120;
        *actual_power_dbm = 10;
    }
}

